2390	// a single command re-enters getSessionsBranchTree several times (List, then
2391	// getFetchingTree for each read), so without it a repo the fetch cannot recover
2392	// — remote has no v1, is unreachable, or refuses auth — would re-pay the whole
2393	// fetch budget on every entry.
2394	func (s *GitStore) tryFetchMetadataBranch(ctx context.Context) bool {
2395		if s.metadataBranchFetcher == nil || s.metadataBranchFetchTried {
2396			return false
2397		}
2398		s.metadataBranchFetchTried = true
2399		if err := s.metadataBranchFetcher(ctx); err != nil {
2400			logging.Debug(ctx, "sessions branch: checkpoint remote fetch failed",
2401				slog.String("ref", s.refs.Read.String()),
2402				slog.String("error", err.Error()),
2403			)
2404			return false
2405		}
2406		return true
2407	}
