2409	// CreateBlobFromContent creates a blob object from in-memory content.
2410	// Exported for use by strategy package (session_test.go)
2411	func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
2412		obj := repo.Storer.NewEncodedObject()
2413		obj.SetType(plumbing.BlobObject)
2414		obj.SetSize(int64(len(content)))
2415	
2416		writer, err := obj.Writer()
2417		if err != nil {
2418			return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
2419		}
2420	
2421		_, err = writer.Write(content)
2422		if err != nil {
2423			_ = writer.Close()
2424			return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
2425		}
2426		if err := writer.Close(); err != nil {
2427			return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
2428		}
2429	
2430		hash, err := repo.Storer.SetEncodedObject(obj)
2431		if err != nil {
2432			return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
2433		}
2434		return hash, nil
2435	}
