2437	// copyMetadataDir copies all files from a directory to the checkpoint path.
2438	// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
2439	func (s *treeWriter) copyMetadataDir(ctx context.Context, metadataDir, sessionDir string, entries map[string]object.TreeEntry) error {
2440		err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
2441			if err != nil {
2442				return err
2443			}
2444	
2445			// Skip symlinks to prevent reading files outside the metadata directory.
2446			// A symlink could point to sensitive files (e.g., /etc/passwd) which would
2447			// then be captured in the checkpoint and stored in git history.
2448			// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
2449			// reports ModeSymlink. We use os.Lstat to check the entry itself.
2450			// This check MUST come before IsDir() because Walk follows symlinked
2451			// directories and would recurse into them otherwise.
2452			linfo, lstatErr := os.Lstat(path)
2453			if lstatErr != nil {
2454				return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
2455			}
2456			if linfo.Mode()&os.ModeSymlink != 0 {
2457				if info.IsDir() {
2458					return filepath.SkipDir
2459				}
2460				return nil
2461			}
2462	
2463			if info.IsDir() {
2464				return nil
2465			}
2466	
2467			// Get relative path within metadata dir
2468			relPath, err := filepath.Rel(metadataDir, path)
2469			if err != nil {
2470				return fmt.Errorf("failed to get relative path for %s: %w", path, err)
2471			}
2472	
2473			// Prevent path traversal via unexpected relative paths outside the metadata dir.
2474			if paths.IsRelativeTraversal(relPath) {
2475				return fmt.Errorf("path traversal detected: %s", relPath)
2476			}
2477	
2478			// Create blob from file with regex-only secrets redaction (the
2479			// eight always-on/opt-in layers).
2480			// Post-commit emits regex-only blobs; the pre-push rewrite
2481			// (strategy/manual_commit_opf_rewrite.go) walks the resulting
2482			// tree, re-redacts these blobs with OPF when enabled, and
2483			// rewrites entire/checkpoints/v1 into OPF-applied (9-layer)
2484			// commits before they leave the local machine.
2485			// No prefix cache here: this path is unreachable in production (no
2486			// production WriteOptions sets MetadataDir) and relPath is not
2487			// session-scoped, so it would key every session to one slot.
2488			blobHash, mode, err := createRedactedBlobFromFile(ctx, s.repo, nil, path, relPath)
2489			if err != nil {
2490				return fmt.Errorf("failed to create blob for %s: %w", path, err)
2491			}
2492	
2493			// Store at checkpoint path (use forward slashes for git tree compatibility on Windows)
2494			fullPath := checkpointSubtreePath(sessionDir, filepath.ToSlash(relPath))
2495			entries[fullPath] = object.TreeEntry{
2496				Name: fullPath,
2497				Mode: mode,
2498				Hash: blobHash,
2499			}
